cols_to_keep &lt;- c("Year", "J-D")

fn_annual &lt;- function(df, id) {
  dft &lt;- df |&gt; 
    select(all_of(cols_to_keep)) |&gt;
    rename(year = Year) |&gt;
    rename(anomaly = `J-D`) |&gt;
    mutate(geographic_id = id) |&gt; 
    mutate(geographic_id = factor(geographic_id, levels=geographic_id_levels)) |&gt; 
    mutate(year = as.integer(year)) |&gt;
    mutate(decade = as.integer(year - (year %% 10) + 10)) |&gt;
    mutate(climate_period = assign_climate_period(year)) |&gt;
    select(geographic_id, climate_period, decade, year, anomaly) |&gt; 
    drop_na()
  return(dft)
}

df1 &lt;- fn_annual(df_raw_g, id="G")
df2 &lt;- fn_annual(df_raw_n, id="N")
df3 &lt;- fn_annual(df_raw_s, id="S")

df_annual &lt;- bind_rows(df1, df2, df3)
df_annual &lt;- df_annual |&gt; filter(year &gt;= analysis_start_year)
rm(df1, df2, df3)




Global and Hemisphere Monthly


Code
cols_to_keep &lt;- c("Year",
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")

fn_monthly &lt;- function(df, id) {
  dft &lt;- df |&gt; 
    select(all_of(cols_to_keep)) |&gt;
    pivot_longer(
      cols=c(Jan,Feb,Mar,Apr,May,Jun,Jul,Aug,Sep,Oct,Nov,Dec), 
      names_to = "month_abbr",
      values_to = "anomaly",
      values_drop_na = TRUE) |&gt;
    rename(year = Year) |&gt;
    mutate(month = match(month_abbr,month.abb)) |&gt; 
    mutate(date = as.Date(sprintf("%04d-%02d-01",year,month))) |&gt; 
    mutate(geographic_id = id) |&gt; 
    mutate(geographic_id = factor(geographic_id, levels=geographic_id_levels)) |&gt; 
    mutate(year = as.integer(year)) |&gt;
    mutate(decade = as.integer(year - (year %% 10) + 10)) |&gt;
    mutate(climate_period = assign_climate_period(year)) |&gt;
    select(geographic_id, climate_period, decade, year, month, date, anomaly)

  return(dft)
}

df1 &lt;- fn_monthly(df_raw_g, id="G")
df2 &lt;- fn_monthly(df_raw_n, id="N")
df3 &lt;- fn_monthly(df_raw_s, id="S")

df_monthly &lt;- bind_rows(df1, df2, df3)
df_monthly &lt;- df_monthly |&gt; filter(year &gt;= analysis_start_year)
rm(df1, df2, df3)




Seasonal Annual
Meteorological seasons are hemisphere dependent:

NH winter, SH summer: December, January, February.
NH spring, SH autumn: March, April, May.
NH summer, SH winter: June, July, August.
NH autumn, SH spring: September, October, November.



Code
cols_to_keep &lt;- c("Year", "DJF", "MAM", "JJA", "SON")

fn_seasonal &lt;- function(df, id) {
  dft &lt;- df |&gt; 
    select(all_of(cols_to_keep)) |&gt;
    pivot_longer(
      cols=c(DJF, MAM, JJA, SON), 
      names_to = "months",
      values_to = "anomaly",
      values_drop_na = TRUE) |&gt;
    rename(year = Year) |&gt;
    mutate(geographic_id = id) |&gt; 
    mutate(geographic_id = factor(geographic_id, geographic_id_levels)) |&gt; 
    mutate(year = as.integer(year)) |&gt;
    mutate(decade = as.integer(year - (year %% 10) + 10)) |&gt;
    mutate(climate_period = assign_climate_period(year)) |&gt;
    mutate(season = case_when(
      geographic_id == "N" & months == "DJF" ~ "Winter",
      geographic_id == "N" & months == "MAM" ~ "Spring",
      geographic_id == "N" & months == "JJA" ~ "Summer",
      geographic_id == "N" & months == "SON" ~ "Autumn",
      geographic_id == "S" & months == "DJF" ~ "Summer",
      geographic_id == "S" & months == "MAM" ~ "Autumn",
      geographic_id == "S" & months == "JJA" ~ "Winter",
      geographic_id == "S" & months == "SON" ~ "Spring"
    ))|&gt;
    select(geographic_id, climate_period, decade, year, season, anomaly)
  return(dft)
}

df1 &lt;- fn_seasonal(df_raw_n, id="N")
df2 &lt;- fn_seasonal(df_raw_s, id="S")

df_seasonal &lt;- bind_rows(df1, df2)

df_seasonal &lt;- df_seasonal |&gt; filter(year &gt;= analysis_start_year)
rm(df1, df2)




Zonal Annual


Code
fn_zonal &lt;- function(df,select_cols,tidy_cols,id) {
  dft &lt;- df |&gt; 
    select(all_of(select_cols)) |&gt;
    pivot_longer(
      cols =  all_of(tidy_cols),
      names_to = "zone",
      values_to = "anomaly",
      values_drop_na = TRUE) |&gt; 
    rename(year = Year) |&gt;
    mutate(zonal_id = id) |&gt;
    mutate(zonal_id = factor(zonal_id)) |&gt;
    mutate(zone = factor(zone, levels=zone_levels)) |&gt;
    mutate(year = as.integer(year)) |&gt;
    mutate(decade = as.integer(year - (year %% 10) + 10)) |&gt; 
    mutate(climate_period = assign_climate_period(year)) |&gt;
    select(zonal_id, zone, climate_period, year, anomaly)
  return(dft) 
}

tidy_cols &lt;- colnames(df_raw_z[,5:7])
select_cols &lt;- c("Year",tidy_cols)
df_z3 &lt;- fn_zonal(df_raw_z, select_cols, tidy_cols, id = "z3")

tidy_cols &lt;- colnames(df_raw_z[,8:15])
select_cols &lt;- c("Year",tidy_cols)
df_z8 &lt;- fn_zonal(df_raw_z, select_cols, tidy_cols, id = "z8")

df_zonal &lt;- bind_rows(df_z3, df_z8)
df_zonal &lt;- df_zonal |&gt; filter(year &gt;= analysis_start_year)
rm(df_z3, df_z8, tidy_cols, select_cols)





